      ToolsOzoneSetAddValues: {
        lexicon: 1,
        id: "tools.ozone.set.addValues",
        defs: {
          main: {
            type: "procedure",
            description: "Add values to a specific set. Attempting to add values to a set that does not exist will result in an error.",
            input: {
              encoding: "application/json",
              schema: {
                type: "object",
                required: ["name", "values"],
                properties: {
                  name: {
                    type: "string",
                    description: "Name of the set to add values to"
                  },
                  values: {
                    type: "array",
                    minLength: 1,
                    maxLength: 1e3,
                    items: {
                      type: "string"
                    },
                    description: "Array of string values to add to the set"
                  }
                }
              }
            }
          }
        }
      },
      ToolsOzoneSetDefs: {
        lexicon: 1,
        id: "tools.ozone.set.defs",
        defs: {
          set: {
            type: "object",
            required: ["name"],
            properties: {
              name: {
                type: "string",
                minLength: 3,
                maxLength: 128
              },
              description: {
                type: "string",
                maxGraphemes: 1024,
                maxLength: 10240
              }
            }
          },
          setView: {
            type: "object",
            required: ["name", "setSize", "createdAt", "updatedAt"],
            properties: {
              name: {
                type: "string",
                minLength: 3,
                maxLength: 128
              },
              description: {
                type: "string",
                maxGraphemes: 1024,
                maxLength: 10240
              },
              setSize: {
                type: "integer"
              },
              createdAt: {
                type: "string",
                format: "datetime"
              },
              updatedAt: {
                type: "string",
                format: "datetime"
              }
            }
          }
        }
      },
